window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f8f07ba46f658958"]={"versions": [{"id": "FIG-f8f07ba46f658958", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (Interaktionsdiagramm mit drei sequenziellen Rahmen <code>seq</code>). Modelliert die standardisierten Interaktions- und Datenflussszenarien zwischen dem AUTOSAR COM-Modul (<code>Com</code>, Services Layer) und dem PDU Router (<code>PduR</code>, Communication Abstraction Layer) für die Bussysteme CAN, LIN und FlexRay.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Komponenten / Module:</li>\n<li><code>«module» Com</code>: AUTOSAR Communication-Modul (Signal- und I-PDU-Verarbeitung, Signal-Packing/-Unpacking, Filterung).</li>\n<li><code>«module» PduR</code>: PDU Router (I-PDU-Routing zwischen busabstrahierenden Schnittstellen und oberen Schichten).</li>\n<li>Schnittstellen & Interaktionen:</li>\n<li>Empfangspfad (<code>seq Reception CAN, LIN, FlexRay</code>):</li>\n<li><code>Com_RxIndication(PduIdType, uint8*)</code>: Callback vom PduR an Com zur Übergabe empfangener I-PDU-Daten.</li>\n<li>Sendepfad mit TriggerTransmit (<code>seq Transmission LIN, FlexRay</code>):</li>\n<li><code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*) :Std_ReturnType</code>: Sendeanforderung von Com an PduR.</li>\n<li><code>Com_TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType**)</code>: Polling-Callback von PduR an Com zur Datenabholung für zeitgesteuerte Busse.</li>\n<li><code>Com_TxConfirmation(PduIdType)</code>: Sendeabschluss-Bestätigung von PduR an Com.</li>\n<li>Direkter Sendepfad (<code>seq Transmission CAN</code>):</li>\n<li><code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*) :Std_ReturnType</code>: Sendeanforderung von Com an PduR.</li>\n<li><code>Com_TxConfirmation(PduIdType)</code>: Sendeabschluss-Bestätigung von PduR an Com.</li>\n<li>Synchroner Rückgabewert: <code>E_OK()</code> als synchrone Antwort auf <code>PduR_ComTransmit</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Reception CAN, LIN, FlexRay</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>PduR ruft bei PDU-Empfang synchron <code>Com_RxIndication(PduIdType, uint8*)</code> auf.</li>\n<li>Com führt die interne Verarbeitung aus (<code>Internal processing()</code>), z. B. Entpacken und Signalrouting.</li>\n<li>Gestrichelte Kontrollrückkehr zum PduR.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Transmission LIN, FlexRay</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Com initiiert die Übertragung via <code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>.</li>\n<li>PduR verarbeitet intern (<code>internal processing()</code>) und antwortet synchron mit <code>E_OK()</code>.</li>\n<li>Zum Sendezeitpunkt im Bus-Fahrplan ruft PduR nach interner Verarbeitung (<code>internal processing()</code>) <code>Com_TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType**)</code> auf, um Nutzdaten abzufragen.</li>\n<li>Com stellt die Daten im Rahmen von <code>Internal processing()</code> bereit und kehrt zurück.</li>\n<li>Nach erfolgreicher Bus-Übertragung ruft PduR <code>Com_TxConfirmation(PduIdType)</code> auf; Com schließt den Vorgang intern ab (<code>Internal processing()</code>) und kehrt zurück.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Transmission CAN</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Com stößt die direkte Übertragung mit <code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*)</code> an.</li>\n<li>PduR quittiert die Anforderung synchron mit <code>E_OK()</code>.</li>\n<li>Nach erfolgter Übertragung meldet PduR den Abschluss über <code>Com_TxConfirmation(PduIdType)</code>. Com führt die interne Nachbereitung aus (<code>Internal processing()</code>) und kehrt zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Definiert die standardisierten Interaktionsabläufe gemäß AUTOSAR COM SWS.</li>\n<li>Unterscheidet architekturell zwischen getriggerten Übertragungen (<code>TriggerTransmit</code> für deterministische, fahrplanbasierte Busse wie LIN und FlexRay) und direkten/ereignisgesteuerten Übertragungen (CAN).</li>\n<li>Spezifische Eigenheiten dieser Release-Fassung (R4.0.3):</li>\n<li><code>Com_RxIndication</code> übergibt Nutzdaten als einfachen Byte-Zeiger <code>uint8*</code> ohne explizite Längenangabe im Struct.</li>\n<li><code>Com_TriggerTransmit</code> verwendet eine Zeiger-auf-Zeiger-Signatur <code>PduInfoType**</code>.</li>\n<li><code>Com_TxConfirmation</code> übermittelt ausschließlich die <code>PduIdType</code> ohne Statusparameter (<code>result</code>).</li>\n<li>Entwickler müssen sicherstellen, dass PDU-IDs in COM und PduR konsistent konfiguriert sind und Daten bei <code>TriggerTransmit</code> reentrant bereitgestellt werden können.</li>\n</ul>"}, {"id": "FIG-a01608a6599520c6", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (Interaktionsdiagramm mit drei sequenziellen Rahmen <code>seq</code>). Modelliert die standardisierten Interaktions- und Datenflussszenarien zwischen dem AUTOSAR COM-Modul (<code>Com</code>, Services Layer) und dem PDU Router (<code>PduR</code>, Communication Abstraction Layer) für die Bussysteme CAN, LIN und FlexRay.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Komponenten / Module:</li>\n<li><code>«module» Com</code>: AUTOSAR Communication-Modul.</li>\n<li><code>«module» PduR</code>: PDU Router.</li>\n<li>Schnittstellen & Interaktionen:</li>\n<li>Empfangspfad (<code>seq Reception CAN, LIN, FlexRay</code>):</li>\n<li><code>Com_RxIndication(PduIdType, PduInfoType*)</code>: Callback vom PduR an Com zur Übergabe empfangener I-PDU-Daten inklusive Längenangabe.</li>\n<li>Sendepfad mit TriggerTransmit (<code>seq Transmission LIN, FlexRay</code>):</li>\n<li><code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*) : Std_ReturnType</code>: Sendeanforderung von Com an PduR.</li>\n<li><code>Com_TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType*)</code>: Polling-Callback von PduR an Com zur Datenabholung mit einfachem Zeiger.</li>\n<li><code>Com_TxConfirmation(PduIdType)</code>: Sendeabschluss-Bestätigung von PduR an Com.</li>\n<li>Direkter Sendepfad (<code>seq Transmission CAN</code>):</li>\n<li><code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*) : Std_ReturnType</code>: Sendeanforderung von Com an PduR.</li>\n<li><code>Com_TxConfirmation(PduIdType)</code>: Sendeabschluss-Bestätigung von PduR an Com.</li>\n<li>Synchroner Rückgabewert: <code>E_OK()</code> als synchrone Antwort auf <code>PduR_ComTransmit</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Reception CAN, LIN, FlexRay</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>PduR übergibt die empfangene PDU synchron über <code>Com_RxIndication(PduIdType, PduInfoType*)</code> an Com.</li>\n<li>Com führt die interne Verarbeitung aus (<code>Internal processing()</code>) und kehrt zum PduR zurück.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Transmission LIN, FlexRay</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Com initiiert die Übertragung mit <code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>.</li>\n<li>PduR führt ein <code>internal processing()</code> aus und quittiert synchron mit <code>E_OK()</code>.</li>\n<li>Vor der Übertragung fordert PduR nach <code>internal processing()</code> über <code>Com_TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType*)</code> die aktuellen Sendedaten an.</li>\n<li>Com verarbeitet die Anforderung (<code>Internal processing()</code>), befüllt die Struktur und kehrt zurück.</li>\n<li>Nach erfolgreichem Versand bestätigt PduR den Abschluss via <code>Com_TxConfirmation(PduIdType)</code>. Com verarbeitet die Bestätigung intern (<code>Internal processing()</code>) und kehrt zurück.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Transmission CAN</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Com ruft direkt <code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*)</code> auf.</li>\n<li>PduR bestätigt synchron mit <code>E_OK()</code>.</li>\n<li>PduR meldet nach erfolgter Übertragung <code>Com_TxConfirmation(PduIdType)</code>. Com führt ein <code>Internal processing()</code> durch und kehrt zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Schnittstellen wurden an die standardisierten BSW-C-Typen harmonisiert:</li>\n<li><code>Com_RxIndication</code> verwendet nun <code>PduInfoType*</code>, wodurch Com neben den Nutzdaten auch die tatsächlich empfangene PDU-Länge übermittelt bekommt.</li>\n<li><code>Com_TriggerTransmit</code> wurde vom Doppelzeiger <code>PduInfoType*<em></code> auf den einfachen Zeiger <code>PduInfoType</em></code> korrigiert.</li>\n<li><code>Com_TxConfirmation</code> bleibt weiterhin auf die reine PDU-ID beschränkt.</li>\n</ul>"}, {"id": "FIG-87566de7ee7c9944", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (Interaktionsdiagramm mit drei sequenziellen Rahmen <code>seq</code>). Modelliert die standardisierten Interaktions- und Datenflussszenarien zwischen dem AUTOSAR COM-Modul (<code>Com</code>, Services Layer) und dem PDU Router (<code>PduR</code>, Communication Abstraction Layer) für die Bussysteme CAN, LIN und FlexRay.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Komponenten / Module:</li>\n<li><code>«module» Com</code>: AUTOSAR Communication-Modul.</li>\n<li><code>«module» PduR</code>: PDU Router.</li>\n<li>Schnittstellen & Interaktionen:</li>\n<li>Empfangspfad (<code>seq Reception CAN, LIN, FlexRay</code>):</li>\n<li><code>Com_RxIndication(PduIdType, PduInfoType*)</code>: Callback vom PduR an Com zur Übergabe empfangener I-PDU-Daten inklusive Längenangabe.</li>\n<li>Sendepfad mit TriggerTransmit (<code>seq Transmission LIN, FlexRay</code>):</li>\n<li><code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*) : Std_ReturnType</code>: Sendeanforderung von Com an PduR.</li>\n<li><code>Com_TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType*)</code>: Polling-Callback von PduR an Com zur Datenabholung mit einfachem Zeiger.</li>\n<li><code>Com_TxConfirmation(PduIdType)</code>: Sendeabschluss-Bestätigung von PduR an Com.</li>\n<li>Direkter Sendepfad (<code>seq Transmission CAN</code>):</li>\n<li><code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*) : Std_ReturnType</code>: Sendeanforderung von Com an PduR.</li>\n<li><code>Com_TxConfirmation(PduIdType)</code>: Sendeabschluss-Bestätigung von PduR an Com.</li>\n<li>Synchroner Rückgabewert: <code>E_OK()</code> als synchrone Antwort auf <code>PduR_ComTransmit</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Reception CAN, LIN, FlexRay</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>PduR übergibt die empfangene PDU synchron über <code>Com_RxIndication(PduIdType, PduInfoType*)</code> an Com.</li>\n<li>Com führt die interne Verarbeitung aus (<code>Internal processing()</code>) und kehrt zum PduR zurück.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Transmission LIN, FlexRay</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Com initiiert die Übertragung mit <code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>.</li>\n<li>PduR führt ein <code>internal processing()</code> aus und quittiert synchron mit <code>E_OK()</code>.</li>\n<li>Vor der Übertragung fordert PduR nach <code>internal processing()</code> über <code>Com_TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType*)</code> die aktuellen Sendedaten an.</li>\n<li>Com verarbeitet die Anforderung (<code>Internal processing()</code>), befüllt die Struktur und kehrt zurück.</li>\n<li>Nach erfolgreichem Versand bestätigt PduR den Abschluss via <code>Com_TxConfirmation(PduIdType)</code>. Com verarbeitet die Bestätigung intern (<code>Internal processing()</code>) und kehrt zurück.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Transmission CAN</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Com ruft direkt <code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*)</code> auf.</li>\n<li>PduR bestätigt synchron mit <code>E_OK()</code>.</li>\n<li>PduR meldet nach erfolgter Übertragung <code>Com_TxConfirmation(PduIdType)</code>. Com führt ein <code>Internal processing()</code> durch und kehrt zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Schnittstellen wurden an die standardisierten BSW-C-Typen harmonisiert:</li>\n<li><code>Com_RxIndication</code> verwendet nun <code>PduInfoType*</code>, wodurch Com neben den Nutzdaten auch die tatsächlich empfangene PDU-Länge übermittelt bekommt.</li>\n<li><code>Com_TriggerTransmit</code> wurde vom Doppelzeiger <code>PduInfoType*<em></code> auf den einfachen Zeiger <code>PduInfoType</em></code> korrigiert.</li>\n<li><code>Com_TxConfirmation</code> bleibt weiterhin auf die reine PDU-ID beschränkt.</li>\n</ul>"}, {"id": "FIG-15dac6759b3b3218", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (Interaktionsdiagramm mit drei sequenziellen Rahmen <code>seq</code>). Modelliert die standardisierten Interaktions- und Datenflussszenarien zwischen dem AUTOSAR COM-Modul (<code>Com</code>, Services Layer) und dem PDU Router (<code>PduR</code>, Communication Abstraction Layer) für die Bussysteme CAN, LIN und FlexRay.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Komponenten / Module:</li>\n<li><code>«module» Com</code>: AUTOSAR Communication-Modul.</li>\n<li><code>«module» PduR</code>: PDU Router.</li>\n<li>Schnittstellen & Interaktionen:</li>\n<li>Empfangspfad (<code>seq Reception CAN, LIN, FlexRay</code>):</li>\n<li><code>Com_RxIndication(PduIdType, const PduInfoType*)</code>: Callback vom PduR an Com zur Übergabe empfangener I-PDU-Daten mit konstantem Pufferzeiger.</li>\n<li>Sendepfad mit TriggerTransmit (<code>seq Transmission LIN, FlexRay</code>):</li>\n<li><code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*) : Std_ReturnType</code>: Sendeanforderung von Com an PduR.</li>\n<li><code>Com_TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType*)</code>: Polling-Callback von PduR an Com zur Datenabholung.</li>\n<li><code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>: Sendeabschluss-Bestätigung von PduR an Com inklusive Übertragungsstatus.</li>\n<li>Direkter Sendepfad (<code>seq Transmission CAN</code>):</li>\n<li><code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*) : Std_ReturnType</code>: Sendeanforderung von Com an PduR.</li>\n<li><code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>: Sendeabschluss-Bestätigung von PduR an Com inklusive Übertragungsstatus.</li>\n<li>Synchroner Rückgabewert: <code>E_OK()</code> als synchrone Antwort auf <code>PduR_ComTransmit</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Reception CAN, LIN, FlexRay</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>PduR ruft synchron <code>Com_RxIndication(PduIdType, const PduInfoType*)</code> auf.</li>\n<li>Com verarbeitet die Daten schreibgeschützt intern (<code>Internal processing()</code>) und kehrt zum PduR zurück.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Transmission LIN, FlexRay</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Com initiiert die Übertragung über <code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>.</li>\n<li>PduR verarbeitet intern (<code>internal processing()</code>) und quittiert synchron mit <code>E_OK()</code>.</li>\n<li>PduR ruft nach internem Processing (<code>internal processing()</code>) den Callback <code>Com_TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType*)</code> auf.</li>\n<li>Com verarbeitet die Anforderung (<code>Internal processing()</code>) und kehrt zurück.</li>\n<li>Nach Übertragung meldet PduR den Abschluss und das Sendeergebnis mit <code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>. Com führt die interne Nachbereitung (<code>Internal processing()</code>) durch und kehrt zurück.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Transmission CAN</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Com initiiert die Sendesequenz über <code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>.</li>\n<li>PduR quittiert synchron mit <code>E_OK()</code>.</li>\n<li>PduR übermittelt nach Abschluss der Busübertragung das Sendeergebnis via <code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>. Com führt die interne Nachbereitung (<code>Internal processing()</code>) durch und kehrt zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Anpassung der BSW-Signaturen:</li>\n<li><code>Com_RxIndication</code> schützt den Nutzdatenpuffer nun explizit durch <code>const PduInfoType*</code> gegen modifizierende Zugriffe durch das aufgerufene Modul.</li>\n<li><code>Com_TxConfirmation</code> wurde um den Statusparameter <code>result: Std_ReturnType</code> erweitert. Dadurch kann Com feststellen, ob die Übertragung erfolgreich war (<code>E_OK</code>) oder scheiterte (<code>E_NOT_OK</code>), und Sendefristenüberwachung (Tx-Deadline-Monitoring) sowie Fehlerbehandlung entsprechend steuern.</li>\n</ul>"}, {"id": "FIG-5fcb18ec3d2b53dd", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (Interaktionsdiagramm mit drei sequenziellen Rahmen <code>seq</code>). Modelliert die standardisierten Interaktions- und Datenflussszenarien zwischen dem AUTOSAR COM-Modul (<code>Com</code>, Services Layer) und dem PDU Router (<code>PduR</code>, Communication Abstraction Layer) für die Bussysteme CAN, LIN und FlexRay.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Komponenten / Module:</li>\n<li><code>«module» Com</code>: AUTOSAR Communication-Modul.</li>\n<li><code>«module» PduR</code>: PDU Router.</li>\n<li>Schnittstellen & Interaktionen:</li>\n<li>Empfangspfad (<code>seq Reception CAN, LIN, FlexRay</code>):</li>\n<li><code>Com_RxIndication(PduIdType, const PduInfoType*)</code>: Callback vom PduR an Com zur Übergabe empfangener I-PDU-Daten mit konstantem Pufferzeiger.</li>\n<li>Sendepfad mit TriggerTransmit (<code>seq Transmission LIN, FlexRay</code>):</li>\n<li><code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*) : Std_ReturnType</code>: Sendeanforderung von Com an PduR.</li>\n<li><code>Com_TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType*)</code>: Polling-Callback von PduR an Com zur Datenabholung.</li>\n<li><code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>: Sendeabschluss-Bestätigung von PduR an Com inklusive Übertragungsstatus.</li>\n<li>Direkter Sendepfad (<code>seq Transmission CAN</code>):</li>\n<li><code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*) : Std_ReturnType</code>: Sendeanforderung von Com an PduR.</li>\n<li><code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>: Sendeabschluss-Bestätigung von PduR an Com inklusive Übertragungsstatus.</li>\n<li>Synchroner Rückgabewert: <code>E_OK()</code> als synchrone Antwort auf <code>PduR_ComTransmit</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Reception CAN, LIN, FlexRay</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>PduR ruft synchron <code>Com_RxIndication(PduIdType, const PduInfoType*)</code> auf.</li>\n<li>Com verarbeitet die Daten schreibgeschützt intern (<code>Internal processing()</code>) und kehrt zum PduR zurück.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Transmission LIN, FlexRay</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Com initiiert die Übertragung über <code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>.</li>\n<li>PduR verarbeitet intern (<code>internal processing()</code>) und quittiert synchron mit <code>E_OK()</code>.</li>\n<li>PduR ruft nach internem Processing (<code>internal processing()</code>) den Callback <code>Com_TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType*)</code> auf.</li>\n<li>Com verarbeitet die Anforderung (<code>Internal processing()</code>) und kehrt zurück.</li>\n<li>Nach Übertragung meldet PduR den Abschluss und das Sendeergebnis mit <code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>. Com führt die interne Nachbereitung (<code>Internal processing()</code>) durch und kehrt zurück.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Transmission CAN</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Com initiiert die Sendesequenz über <code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>.</li>\n<li>PduR quittiert synchron mit <code>E_OK()</code>.</li>\n<li>PduR übermittelt nach Abschluss der Busübertragung das Sendeergebnis via <code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>. Com führt die interne Nachbereitung (<code>Internal processing()</code>) durch und kehrt zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Anpassung der BSW-Signaturen:</li>\n<li><code>Com_RxIndication</code> schützt den Nutzdatenpuffer nun explizit durch <code>const PduInfoType*</code> gegen modifizierende Zugriffe durch das aufgerufene Modul.</li>\n<li><code>Com_TxConfirmation</code> wurde um den Statusparameter <code>result: Std_ReturnType</code> erweitert. Dadurch kann Com feststellen, ob die Übertragung erfolgreich war (<code>E_OK</code>) oder scheiterte (<code>E_NOT_OK</code>), und Sendefristenüberwachung (Tx-Deadline-Monitoring) sowie Fehlerbehandlung entsprechend steuern.</li>\n</ul>"}, {"id": "FIG-7641b9c356846a95", "releases": ["R20-11", "R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (Interaktionsdiagramm mit drei sequenziellen Rahmen <code>seq</code>). Modelliert die standardisierten Interaktions- und Datenflussszenarien zwischen dem AUTOSAR COM-Modul (<code>Com</code>, Services Layer) und dem PDU Router (<code>PduR</code>, Communication Abstraction Layer) für die Bussysteme CAN, LIN und FlexRay.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Komponenten / Module:</li>\n<li><code>«module» Com</code>: AUTOSAR Communication-Modul.</li>\n<li><code>«module» PduR</code>: PDU Router.</li>\n<li>Schnittstellen & Interaktionen:</li>\n<li>Empfangspfad (<code>seq Reception CAN, LIN, FlexRay</code>):</li>\n<li><code>Com_RxIndication(PduIdType, const PduInfoType*)</code>: Callback vom PduR an Com zur Übergabe empfangener I-PDU-Daten mit konstantem Pufferzeiger.</li>\n<li>Sendepfad mit TriggerTransmit (<code>seq Transmission LIN, FlexRay</code>):</li>\n<li><code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*) : Std_ReturnType</code>: Sendeanforderung von Com an PduR.</li>\n<li><code>Com_TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType*)</code>: Polling-Callback von PduR an Com zur Datenabholung.</li>\n<li><code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>: Sendeabschluss-Bestätigung von PduR an Com inklusive Übertragungsstatus.</li>\n<li>Direkter Sendepfad (<code>seq Transmission CAN</code>):</li>\n<li><code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*) : Std_ReturnType</code>: Sendeanforderung von Com an PduR.</li>\n<li><code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>: Sendeabschluss-Bestätigung von PduR an Com inklusive Übertragungsstatus.</li>\n<li>Synchroner Rückgabewert: <code>E_OK()</code> als synchrone Antwort auf <code>PduR_ComTransmit</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Reception CAN, LIN, FlexRay</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>PduR ruft synchron <code>Com_RxIndication(PduIdType, const PduInfoType*)</code> auf.</li>\n<li>Com verarbeitet die Daten schreibgeschützt intern (<code>Internal processing()</code>) und kehrt zum PduR zurück.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Transmission LIN, FlexRay</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Com initiiert die Übertragung über <code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>.</li>\n<li>PduR verarbeitet intern (<code>internal processing()</code>) und quittiert synchron mit <code>E_OK()</code>.</li>\n<li>PduR ruft nach internem Processing (<code>internal processing()</code>) den Callback <code>Com_TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType*)</code> auf.</li>\n<li>Com verarbeitet die Anforderung (<code>Internal processing()</code>) und kehrt zurück.</li>\n<li>Nach Übertragung meldet PduR den Abschluss und das Sendeergebnis mit <code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>. Com führt die interne Nachbereitung (<code>Internal processing()</code>) durch und kehrt zurück.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequenz <code>Transmission CAN</code>:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Com initiiert die Sendesequenz über <code>PduR_ComTransmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>.</li>\n<li>PduR quittiert synchron mit <code>E_OK()</code>.</li>\n<li>PduR übermittelt nach Abschluss der Busübertragung das Sendeergebnis via <code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code>. Com führt die interne Nachbereitung (<code>Internal processing()</code>) durch und kehrt zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Anpassung der BSW-Signaturen:</li>\n<li><code>Com_RxIndication</code> schützt den Nutzdatenpuffer nun explizit durch <code>const PduInfoType*</code> gegen modifizierende Zugriffe durch das aufgerufene Modul.</li>\n<li><code>Com_TxConfirmation</code> wurde um den Statusparameter <code>result: Std_ReturnType</code> erweitert. Dadurch kann Com feststellen, ob die Übertragung erfolgreich war (<code>E_OK</code>) oder scheiterte (<code>E_NOT_OK</code>), und Sendefristenüberwachung (Tx-Deadline-Monitoring) sowie Fehlerbehandlung entsprechend steuern.</li>\n</ul>"}], "trans": [{"from": "FIG-f8f07ba46f658958", "to": "FIG-a01608a6599520c6", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>Com_RxIndication</code>: Parametertyp für den Nutzdatenpuffer von <code>uint8<em></code> auf <code>PduInfoType</em></code> geändert.</li>\n<li><code>Com_TriggerTransmit</code>: Parametertyp für den Nutzdatenpuffer von Doppelzeiger <code>PduInfoType*<em></code> auf einfachen Zeiger <code>PduInfoType</em></code> korrigiert.</li>\n<li><code>PduR_ComTransmit</code>: Leerzeichen vor dem Rückgabetyp-Doppelpunkt eingefügt (<code>:Std_ReturnType</code> zu <code>: Std_ReturnType</code>).</li>\n</ul>"}, {"from": "FIG-a01608a6599520c6", "to": "FIG-87566de7ee7c9944", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-87566de7ee7c9944", "to": "FIG-15dac6759b3b3218", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>Com_RxIndication</code>: Parametertyp um <code>const</code>-Qualifizierer erweitert (<code>const PduInfoType<em></code> statt <code>PduInfoType</em></code>).</li>\n<li><code>Com_TxConfirmation</code>: Signatur in beiden Sende-Szenarien (<code>Transmission LIN, FlexRay</code> und <code>Transmission CAN</code>) um den Ergebnisparameter <code>Std_ReturnType</code> erweitert (<code>Com_TxConfirmation(PduIdType, Std_ReturnType)</code> statt <code>Com_TxConfirmation(PduIdType)</code>).</li>\n</ul>"}, {"from": "FIG-15dac6759b3b3218", "to": "FIG-5fcb18ec3d2b53dd", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>PduR_ComTransmit</code>: Leerzeichen vor dem Doppelpunkt des Rückgabetyps entfernt (<code><em>) : Std_ReturnType</code> zu <code></em>): Std_ReturnType</code>).</li>\n<li>Diagramm-Layout: Neu-Rendering mit leicht angepasster Skalierung und Typografie.</li>\n</ul>"}, {"from": "FIG-5fcb18ec3d2b53dd", "to": "FIG-7641b9c356846a95", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
